void sort_quicksort_variant_1(int* arr, int low, int high) {
    if (low >= high) return;
    int pivot = arr[high];
    int i = low - 1;
    for (int j = low; j < high; j++) {
        if (arr[j] <= pivot) {
            i++;
            int t = arr[i]; arr[i] = arr[j]; arr[j] = t;
        }
    }
    int t = arr[i + 1]; arr[i + 1] = arr[high]; arr[high] = t;
    int pi = i + 1;
    sort_quicksort_variant_1(arr, low, pi - 1);
    sort_quicksort_variant_1(arr, pi + 1, high);
}

